import React, { useState, useRef, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import ScheduleTable from "../../components/ScheduleTable/ScheduleTable";
import "./OrarToti.css";

const OrarToti = () => {
  const navigate = useNavigate();
  const { an, grupa } = useParams();

  const [activeDropdown, setActiveDropdown] = useState(null);
  const [selectedGroup, setSelectedGroup] = useState(null);
  const [section, setSection] = useState(null);
  const [scheduleData, setScheduleData] = useState([]);
  const dropdownRefs = useRef([]);

  const [sali, setSali] = useState([]);
  const [dotariSala, setDotariSala] = useState(null);
  const [profesori, setProfesori] = useState([]);
  const [discipline, setDiscipline] = useState([]);

  // Selectare săli
  const handleEtajSelect = (etaj) => {
    fetch(`http://localhost:34101/sali/etaj/${etaj}`)
      .then((res) => res.json())
      .then((data) => setSali(data))
      .catch((err) => console.error("Eroare la preluarea sălilor:", err));
  };

  // Selectare sală
  const handleSalaSelect = (numeSala) => {
    setSelectedGroup(numeSala);
    setActiveDropdown(null); // Închide dropdown-ul
    fetch(`http://localhost:34101/orar/sala/${numeSala}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar sala:", err));
  };

  // Afișează dotările sălii
  const handleShowDotari = () => {
    fetch(`http://localhost:34101/sali/nume/${selectedGroup}`)
      .then((res) => res.json())
      .then((data) => setDotariSala(data[0]))
      .catch((err) => console.error("Eroare la dotări:", err));
  };

  // Selectarea profesorilor
  const handleProfesorSelect = (profesor) => {
    setSelectedGroup(profesor);
    setActiveDropdown(null);
    fetch(`http://localhost:34101/orar/profesor/${profesor}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar profesor:", err));
  };

  // Selectarea disciplinelor
  const handleDisciplinaSelect = (disciplina) => {
    setSelectedGroup(disciplina);
    setActiveDropdown(null);
    fetch(`http://localhost:34101/orar/disciplina/${disciplina}`)
      .then((res) => res.json())
      .then((data) => setScheduleData(data))
      .catch((err) => console.error("Eroare la orar disciplină:", err));
  };

  const toggleDropdown = (index, e) => {
    e.stopPropagation();
    setActiveDropdown((prev) => (prev === index ? null : index));
    setSelectedGroup(null);
  };

  const handleClickOutside = (event) => {
    if (dropdownRefs.current.every((ref) => ref && !ref.contains(event.target))) {
      setActiveDropdown(null);
    }
  };

  useEffect(() => {
    document.addEventListener("click", handleClickOutside);
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  // Dacă vin parametri din URL, aduce orarul
  useEffect(() => {
    if (an && grupa) {
      const anLabel = `Anul ${an}`;
      setSelectedGroup(`${anLabel} - ${grupa}`);
      setSection("studenti");

      const url = `http://localhost:34101/orar/grupa/${an}/${grupa}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setScheduleData(data);
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului:", err);
        });
    }
  }, [an, grupa]);

  // Funcții pentru a obține profesori și discipline
  useEffect(() => {
    fetch("http://localhost:34101/profesori")
      .then((res) => res.json())
      .then((data) => setProfesori(data))
      .catch((err) => console.error("Eroare la preluarea profesorilor:", err));

    fetch("http://localhost:34101/disciplina")
      .then((res) => res.json())
      .then((data) => setDiscipline(data))
      .catch((err) => console.error("Eroare la preluarea disciplinelor:", err));
  }, []);

  const buttons = [
    {
      label: "Anul 1",
      icon: "1️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "I1X1", "I1X2", "I1X3", "I1X4"],
    },
    {
      label: "Anul 2",
      icon: "2️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "I1X1", "I1X2", "I1X3", "I1X4"],
    },
    {
      label: "Anul 3",
      icon: "3️⃣",
      options: ["A1", "A2", "A3", "A4", "A5", "B1", "B2", "B3", "B4", "E1", "E2", "E3", "X"],
    },
    {
      label: "Master Anul 1",
      icon: "🎓",
      options: [
        "Inteligența Artificială și Optimizare",
        "Ingineria Sistemelor Soft",
        "Lingvistica Computațională",
        "Studii Avansate în Informatică",
        "Sisteme Distribuite",
        "Securitatea Informațiilor",
      ],
    },
    {
      label: "Master Anul 2",
      icon: "🎓",
      options: [
        "Inteligența Artificială și Optimizare",
        "Ingineria Sistemelor Soft",
        "Lingvistica Computațională",
        "Studii Avansate în Informatică",
        "Sisteme Distribuite",
        "Securitatea Informațiilor",
      ],
    },
  ];

  return (
    <div className="orar-container">
      {selectedGroup ? (
        <div className="orar-afisat">
          <h3>Orar pentru {selectedGroup}</h3>
          <ScheduleTable schedule={scheduleData} title={`Orar pentru ${selectedGroup}`} />
          <button
            className="orar-button inapoi"
            onClick={() => {
              setSelectedGroup(null);
              setScheduleData([]);
              navigate("/app/orar");
            }}
          >
            🔙 Înapoi
          </button>
        </div>
      ) : (
        <>
          <div className="orar-titlu">
            <h1>Orar</h1>
            {!section && <h2>Alege o categorie</h2>}
            {section === "studenti" && <h2>Alege anul și grupa</h2>}
            {section === "profesori" && <h2>Alege profesorul</h2>}
            {section === "discipline" && <h2>Alege disciplina</h2>}
          </div>

          {!section && (
            <div className="orar-buttons">
              <button className="orar-button" onClick={() => setSection("studenti")}>🎓 Orar Studenți</button>
              <button className="orar-button" onClick={() => setSection("profesori")}>👨‍🏫 Orar Profesori</button>
              <button className="orar-button" onClick={() => setSection("discipline")}>📚 Orar Discipline</button>
            </div>
          )}

          {section === "profesori" && (
            <div className="orar-buttons">
              {profesori.map((profesor) => (
                <button key={profesor} className="orar-button" onClick={() => handleProfesorSelect(profesor)}>
                  {profesor}
                </button>
              ))}
            </div>
          )}

          {section === "discipline" && (
            <div className="orar-buttons">
              {discipline.map((disciplina) => (
                <button key={disciplina} className="orar-button" onClick={() => handleDisciplinaSelect(disciplina)}>
                  {disciplina}
                </button>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default OrarToti;
